def maximum(values):
    if not values:
        return None
    best = values[0]
    for value in values[1:]:
        best = max(best, value)
    return best

def insertion_sort(a):
    for i in range(1, len(a)):
        value, j = a[i], i - 1
        while j >= 0 and a[j] > value:
            a[j + 1] = a[j]
            j -= 1
        a[j + 1] = value
    return a

def balanced(text):
    stack = []
    pairs = {"(": ")", "[": "]", "{": "}"}
    for char in text:
        if char in pairs:
            stack.append(pairs[char])
        elif not stack or stack.pop() != char:
            return False
    return not stack

def search(a, target):
    lo, hi = 0, len(a) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if a[mid] == target:
            return mid
        if a[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def frequencies(values):
    counts = {}
    for value in values:
        counts[value] = counts.get(value, 0) + 1
    return counts

def palindrome(s):
    left, right = 0, len(s) - 1
    while left < right:
        if s[left] != s[right]:
            return False
        left += 1
        right -= 1
    return True

def inorder(node):
    if node is None:
        return []
    return inorder(node.left) + [node.value] + inorder(node.right)

import heapq
def kth_largest(values, k):
    if not 1 <= k <= len(values):
        raise ValueError("Invalid k")
    heap = []
    for value in values:
        heapq.heappush(heap, value)
        if len(heap) > k:
            heapq.heappop(heap)
    return heap[0]

def reachable(graph, start):
    seen, pending = set(), [start]
    while pending:
        node = pending.pop()
        if node in seen:
            continue
        seen.add(node)
        pending.extend(graph.get(node, []))
    return seen

def ways(n):
    if n < 0:
        return 0
    previous, current = 1, 1
    for _ in range(n):
        previous, current = current, previous + current
    return previous

def can_reach_end(jumps):
    farthest = 0
    for i, jump in enumerate(jumps):
        if i > farthest:
            return False
        farthest = max(farthest, i + jump)
    return bool(jumps)

def single_number(values):
    answer = 0
    for value in values:
        answer ^= value
    return answer

def insert(root, word):
    node = root
    for char in word:
        node = node.setdefault(char, {})
    node[None] = True

def contains(root, word):
    node = root
    for char in word:
        if char not in node:
            return False
        node = node[char]
    return None in node
